export class Media2Client {
  readonly #device: Device

  constructor(device: Device) {
    this.#device = device
  }

  /**
   * Retrieve the profile with the specified token or all defined media profiles. If no Type is provided
   * the returned profiles shall contain no configuration information. If a single Type with value 'All'
   * is provided the returned profiles shall include all associated configurations. Otherwise the
   * requested list of configurations shall for each profile include the configurations present as Type.
   *
   * @param request - The `GetProfiles` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetProfilesResponse`
   */
  getProfiles(request?: GetProfilesRequest, options?: CallOptions): Promise<GetProfilesResponse> {
    return this.#device.call(GetProfiles, request, options)
  }

  /**
   * This operation requests a URI that can be used to initiate a live media stream using RTSP as the
   * control protocol. The returned URI shall remain valid indefinitely even if the profile is changed.
   * Defined stream types are RtspUnicast RTSP streaming RTP as UDP Unicast. RtspMulticast RTSP streaming
   * RTP as UDP Multicast. RtspsUnicast Secure RTSP streaming with SRTP as UDP Unicast. RtspsMulticast
   * Secure RTSP streaming with SRTP as UDP Multicast. RTSP RTSP streaming RTP over TCP. RtspOverHttp
   * Tunneling both the RTSP control channel and the RTP stream over HTTP or HTTPS. If a multicast stream
   * is requested at least one of VideoEncoder2Configuration, AudioEncoder2Configuration and
   * MetadataConfiguration shall have a valid multicast setting. For full compatibility with other ONVIF
   * services a device should not generate Uris longer than 128 octets.
   *
   * @param request - The `GetStreamUri` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetStreamUriResponse`
   */
  getStreamUri(request: GetStreamUriRequest, options?: CallOptions): Promise<GetStreamUriResponse> {
    return this.#device.call(GetStreamUri, request, options)
  }

  /**
   * A client uses the GetSnapshotUri command to obtain a JPEG snapshot from the device. The returned URI
   * shall remain valid indefinitely even if the profile is changed. The URI can be used for acquiring a
   * JPEG image through an HTTP GET operation. The image encoding will always be JPEG regardless of the
   * encoding setting in the media profile. The Jpeg settings (like resolution or quality) may be taken
   * from the profile if suitable. The provided image will be updated automatically and independent from
   * calls to GetSnapshotUri.
   *
   * @param request - The `GetSnapshotUri` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetSnapshotUriResponse`
   */
  getSnapshotUri(request: GetSnapshotUriRequest, options?: CallOptions): Promise<GetSnapshotUriResponse> {
    return this.#device.call(GetSnapshotUri, request, options)
  }

  /**
   * By default this operation lists all existing video source configurations for a device. Provide a
   * profile token to list only configurations that are compatible with the profile. If a configuration
   * token is provided only a single configuration will be returned.
   *
   * @param request - The `GetVideoSourceConfigurations` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetVideoSourceConfigurationsResponse`
   */
  getVideoSourceConfigurations(
    request?: GetConfiguration,
    options?: CallOptions
  ): Promise<GetVideoSourceConfigurationsResponse> {
    return this.#device.call(GetVideoSourceConfigurations, request, options)
  }

  /**
   * By default this operation lists all existing video encoder configurations for a device. Provide a
   * profile token to list only configurations that are compatible with the profile. If a configuration
   * token is provided only a single configuration will be returned.
   *
   * @param request - The `GetVideoEncoderConfigurations` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetVideoEncoderConfigurationsResponse`
   */
  getVideoEncoderConfigurations(
    request?: GetConfiguration,
    options?: CallOptions
  ): Promise<GetVideoEncoderConfigurationsResponse> {
    return this.#device.call(GetVideoEncoderConfigurations, request, options)
  }

  /**
   * This operation returns the available options (supported values and ranges for video encoder
   * configuration parameters) when the video encoder parameters are reconfigured. This response contains
   * the available video encoder configuration options. If a video encoder configuration is specified,
   * the options shall concern that particular configuration. If a media profile is specified, the
   * options shall be compatible with that media profile. If no tokens are specified, the options shall
   * be considered generic for the device.
   *
   * @param request - The `GetVideoEncoderConfigurationOptions` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetVideoEncoderConfigurationOptionsResponse`
   */
  getVideoEncoderConfigurationOptions(
    request?: GetConfiguration,
    options?: CallOptions
  ): Promise<GetVideoEncoderConfigurationOptionsResponse> {
    return this.#device.call(GetVideoEncoderConfigurationOptions, request, options)
  }

  /**
   * This operation modifies a video encoder configuration. Running streams using this configuration may
   * be immediately updated according to the new settings. The changes are not guaranteed to take effect
   * unless the client requests a new stream URI and restarts any affected stream. NVC methods for
   * changing a running stream are out of scope for this specification. SessionTimeout is provided as a
   * hint for keeping rtsp session by a device. If necessary the device may adapt parameter values for
   * SessionTimeout elements without returning an error. For the time between keep alive calls the client
   * shall adhere to the timeout value signaled via RTSP.
   *
   * @param request - The `SetVideoEncoderConfiguration` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetVideoEncoderConfigurationResponse`
   */
  setVideoEncoderConfiguration(
    request: SetVideoEncoderConfigurationRequest,
    options?: CallOptions
  ): Promise<SetConfigurationResponse> {
    return this.#device.call(SetVideoEncoderConfiguration, request, options)
  }
}
